/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Exports the contents of a grid (using the selected order and filters) to a PDF file. &IsAuthorized = SecGAMIsAuthByFunctionalityKey.Udp(!'trnsunidadesww_Execute') If &IsAuthorized
LoadWWPContext.Call(&WWPContext)
Do 'LoadGridState'
&Title = "Lista de Unidade de Medida"
//Report Template Source Header &AppName = "DVelop Software Solutions" &Phone = !"+1 550 8923" &Mail = !"info@mail.com" &Website = !"http://www.web.com" &AddressLine1 = !"French Boulevard 2859" &AddressLine2 = !"Downtown" &AddressLine3 = !"Paris, France" Print printTitle End Footer &PageInfo = "Page: " + &Page.ToString().Trim() &DateInfo = "Date: " + &Today.ToFormattedString() Print printFooter End
Do 'PrintFilters'
Do 'PrintColumnTitles'
Do 'PrintData'
Do 'PrintFooter'
EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
Sub 'PrintFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'UNIDESCRICAO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &uniDescricao1.FromString(&GridStateDynamicFilter.Value) If not &uniDescricao1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilteruniDescricaoDescription = format('%1 (%2)', "Descricao", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &FilteruniDescricaoDescription = format('%1 (%2)', "Descricao", "WWP_FilterContains") EndCase &uniDescricao = &uniDescricao1 print printBlockFilteruniDescricao EndIf EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'UNIDESCRICAO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &uniDescricao2.FromString(&GridStateDynamicFilter.Value) If not &uniDescricao2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilteruniDescricaoDescription = format('%1 (%2)', "Descricao", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &FilteruniDescricaoDescription = format('%1 (%2)', "Descricao", "WWP_FilterContains") EndCase &uniDescricao = &uniDescricao2 print printBlockFilteruniDescricao EndIf EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'UNIDESCRICAO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &uniDescricao3.FromString(&GridStateDynamicFilter.Value) If not &uniDescricao3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilteruniDescricaoDescription = format('%1 (%2)', "Descricao", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &FilteruniDescricaoDescription = format('%1 (%2)', "Descricao", "WWP_FilterContains") EndCase &uniDescricao = &uniDescricao3 print printBlockFilteruniDescricao EndIf EndCase EndIf EndIf EndIf If not &TFuniDescricao_Sel.IsEmpty() print printBlockTFuniDescricao_Sel Else If not &TFuniDescricao.IsEmpty() print printBlockTFuniDescricao EndIf EndIf If not &TFuniFracao_Sel.IsEmpty() print printBlockTFuniFracao_Sel Else If not &TFuniFracao.IsEmpty() print printBlockTFuniFracao EndIf EndIf &TFuniStatus_Sels.FromJson(&TFuniStatus_SelsJson) If not &TFuniStatus_Sels.Count = 0 &i = 1 For &TFuniStatus_Sel in &TFuniStatus_Sels If &i = 1 &TFuniStatus_SelDscs = '' Else &TFuniStatus_SelDscs += ', ' EndIf &FilterTFuniStatus_SelValueDescription = '' Do Case Case &TFuniStatus_Sel.ToString().Trim() = !"A" &FilterTFuniStatus_SelValueDescription = "Ativo"
Case &TFuniStatus_Sel.ToString().Trim() = !"I" &FilterTFuniStatus_SelValueDescription = "Inativo"
EndCase
&TFuniStatus_SelDscs += &FilterTFuniStatus_SelValueDescription &i += 1 EndFor print printBlockTFuniStatus_Sel EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintColumnTitles'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
print printBlockBeforeGrid print printBlockLines_titles
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For each trnsunidades order uniDescricao when &OrderedBy = 1 AND &OrderedDsc = False order (uniDescricao) when &OrderedBy = 1 AND &OrderedDsc = True order uniFracao when &OrderedBy = 2 AND &OrderedDsc = False order (uniFracao) when &OrderedBy = 2 AND &OrderedDsc = True order uniStatus when &OrderedBy = 3 AND &OrderedDsc = False order (uniStatus) when &OrderedBy = 3 AND &OrderedDsc = True
using trnsunidadesWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &uniDescricao1, &DynamicFiltersEnabled2, &DynamicFiltersSelector2, &DynamicFiltersOperator2 , &uniDescricao2, &DynamicFiltersEnabled3, &DynamicFiltersSelector3, &DynamicFiltersOperator3, &uniDescricao3, &TFuniDescricao , &TFuniDescricao_Sel, &TFuniFracao, &TFuniFracao_Sel, &TFuniStatus_Sels) Where prefCodigo = &prefCodigo &uniStatusDescription = '' Do Case Case uniStatus.ToString().Trim() = !"A" &uniStatusDescription = "Ativo"
Case uniStatus.ToString().Trim() = !"I" &uniStatusDescription = "Inativo"
EndCase
Do 'BeforePrintLine' print printBlockLines_data Do 'AfterPrintLine' EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnsunidadesWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnsunidadesWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnsunidadesWWGridState")) Endif
&OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFUNIDESCRICAO" &TFuniDescricao.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFUNIDESCRICAO_SEL" &TFuniDescricao_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFUNIFRACAO" &TFuniFracao.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFUNIFRACAO_SEL" &TFuniFracao_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFUNISTATUS_SEL" &TFuniStatus_SelsJson = &GridStateFilterValue.Value &TFuniStatus_Sels.FromJson(&TFuniStatus_SelsJson) EndCase EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'BeforePrintLine'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'AfterPrintLine'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
